// IconSizeLookup wraps gtk_icon_size_lookup
// 
// The function takes the following parameters:
// 
// 	- size int32: an icon size (#GtkIconSize) 
// 
// The function returns the following values:
// 
// 	- width int32: location to store icon width 
// 	- height int32: location to store icon height 
// 	- goret bool 
//
// Obtains the pixel size of a semantic icon size @size:
// #GTK_ICON_SIZE_MENU, #GTK_ICON_SIZE_BUTTON, etc.  This function
// isn’t normally needed, gtk_icon_theme_load_icon() is the usual
// way to get an icon for rendering, then just look at the size of
// the rendered pixbuf. The rendered pixbuf may not even correspond to
// the width/height returned by gtk_icon_size_lookup(), because themes
// are free to render the pixbuf however they like, including changing
// the usual size.
func IconSizeLookup(size int32) (int32, int32, bool) {
	var carg1 C.GtkIconSize // in, none, casted
	var carg2 C.gint        // out, full, casted
	var carg3 C.gint        // out, full, casted
	var cret  C.gboolean    // return

	carg1 = C.GtkIconSize(size)

	cret = C.gtk_icon_size_lookup(carg1, &carg2, &carg3)
	runtime.KeepAlive(size)

	var width  int32
	var height int32
	var goret  bool

	width = int32(carg2)
	height = int32(carg3)
	if cret != 0 {
		goret = true
	}

	return width, height, goret
}

