	// on_size_allocate (GtkWidget *widget, GtkAllocation *allocation)
	// {
	//   int new_width, new_height;
	// 
	//   gtk_window_get_size (GTK_WINDOW (widget), &amp;new_width, &amp;new_height);
	// 
	//   ...
	// }
	// ]|
