	// 
	// |[
	//   GtkRadioMenuItem *last_item = NULL;
	// 
	//   while ( ...more items to add... )
	//     {
	//       GtkRadioMenuItem *radio_item;
	// 
	//       radio_item = gtk_radio_menu_item_new (...);
	// 
	//       gtk_radio_menu_item_join_group (radio_item, last_item);
	//       last_item = radio_item;
